      "output": "(()=>{const F=window.F,TH=F.THREE,S=F.SHEET,L=S.look,P=S.palette,Y=L.days,N=Y.count,t0=Y.t0,st=Y.step,WK=L.weeks;\nconst dn=s=>{let[y,m,d]=String(s).slice(0,10).split('-').map(Number);if(m<3){y--;m+=12}return 365*y+(y/4|0)-(y/100|0)+(y/400|0)+((153*(m-3)+2)/5|0)+d};\nconst MN=['January','February','March','April','May','June','July','August','September','October','November','December'];\nconst ML=y=>[31,y%4==0&&(y%100!=0||y%400==0)?29:28,31,30,31,30,31,31,30,31,30,31];\nconst fd=i=>{let[y,m,d]=Y.first.split('-').map(Number);d+=i;while(d>ML(y)[m-1]){d-=ML(y)[m-1];m++;if(m>12){m=1;y++}}return d+' '+MN[m-1]+' '+y};\nconst num=v=>Array.isArray(v)?v.length:(+v||0),D0=dn(Y.first);\nconst C=(()=>{const D=window.FILM_DATA||{},c=new Array(N).fill(0),a=D.days||D.daily||D.perDay||D.commitsByDay||D.timeline;\nconst put=(d,v)=>{const i=typeof d=='number'?d:dn(d)-D0;if(i>=0&&i<N&&isFinite(i))c[i]+=v};\nif(Array.isArray(a))a.forEach((e,i)=>typeof e=='number'?put(i,e):put(e.date??e.day??i,num(e.commits??e.count??e.n??e.c)));\nelse if(a&&typeof a=='object')for(const k in a)put(k,num(a[k]));\nelse if(Array.isArray(D.commits))D.commits.forEach(e=>put(e.date??e.day??e.t,1));\nreturn c})();\nconst cum=[0];C.forEach((v,i)=>cum.push(cum[i]+v));\nlet bi=0;C.forEach((v,i)=>{if(v>C[bi])bi=i});\nconst tb=L.busiestDayT,bw=WK.filter(t=>t<=tb+1e-6).length-1,SG=64,RW=L.ringWidth,RR=L.worldRadius,ry=L.terrainMaxHeight+0.05;\nconst dayAt=T=>T<t0-1e-6?0:Math.min(N,Math.floor((T-t0)/st+1e-6)+1);\nconst md=S.modules.find(m=>m.id=='rings'),sp=md&&md.span||[0,F.LENGTH];\nlet R=[];\nF.scene('rings',{start:sp[0],end:sp[1],\nsetup(root){const ac=new TH.Color(P.accent);R=WK.map((t,w)=>{const r=RR*(0.26+0.11*w),g=new TH.RingGeometry(r-RW/2,r+RW/2,SG,1);g.rotateX(-Math.PI/2);g.translate(0,ry,0);\nconst m=new TH.MeshStandardMaterial({color:ac,emissive:ac,emissiveIntensity:0,roughness:0.7,metalness:0,transparent:true,opacity:0,depthWrite:false,side:TH.DoubleSide});\nconst o=new TH.Mesh(g,m);o.renderOrder=2;o.name='ring'+(w+1);root.add(o);return{o,g,m,t:t,w}})},\nupdate(T,lo,info){for(const q of R){const k=F.ease.arrive(F.win(T,q.t,st)),b=q.w==bw?F.ease.inOut(F.win(T,tb,0.5)):0;\nq.o.visible=T>=q.t;q.g.setDrawRange(0,6*Math.max(1,Math.ceil(SG*k)));\nq.m.opacity=k*F.lerp(L.ringOpacity,L.busiestRingOpacity,b);q.m.emissiveIntensity=2.5*b}\nconst c=info&&info.ctx2d;if(!c)return;const w=info.W||F.W,h=info.H||F.H,x0=0.06*w,x1=0.94*w,bw2=x1-x0,yb=0.088*h,fr=F.clamp((T-t0)/(st*(N-1)),0,1),n=dayAt(T),mx=Math.max(1,...C);\nc.save();c.fillStyle=P.terrain;c.fillRect(x0,yb,bw2,Math.max(1,0.003*h));c.fillStyle=P.accent;c.fillRect(x0,yb,bw2*fr,Math.max(1,0.003*h));\nfor(let i=0;i<n;i++){const hh=0.012*h*C[i]/mx;if(hh>0){c.fillStyle=i==bi&&T>=tb?P.ink:P.accent;c.fillRect(x0+bw2*i/(N-1)-0.0012*w,yb-hh,0.0024*w,hh)}}\nc.restore();\nconst z=0.018*h,o={size:z,font:S.fonts.mono,weight:S.fonts.weights.mono,baseline:'top'},yt=0.055*h,yd=yb+0.012*h;\n[['Day '+n,x0,yt,'left',P.ink],[cum[n]+' commits',x1,yt,'right',P.ink],[n?fd(n-1):'',(x0+x1)/2,yt,'center',P.muted],[fd(0),x0,yd,'left',P.muted],[fd(N-1),x1,yd,'right',P.muted]].forEach(([s,x,y,a,col])=>{if(s)F.text(c,s,x,y,{...o,align:a,color:col,maxWidth:0.24*w})})}});\nconst tot=cum[N],wd=C.filter(v=>v>0).length,ix=s=>dn(s)-D0,fb=(()=>{const D=window.FILM_DATA,b=D&&D.born;if(!b)return;if(Array.isArray(b)){const e=b.find(e=>/backend/i.test(e.id||e.name||e.district||''));return e&&(e.date||e.born||e.day)}return b.backend&&(b.backend.date||b.backend)})();\n[['rings: FILM_DATA days = 51',()=>({ok:!!window.FILM_DATA&&dn(Y.last)-D0+1==N,detail:'days '+N+(window.FILM_DATA?'':' (no FILM_DATA)')})],\n['rings: 789 commits in all',()=>({ok:tot==789,detail:'total '+tot})],\n['rings: 42 days with commits',()=>({ok:wd==Y.withCommits&&wd==42,detail:'days with commits '+wd})],\n['rings: 2026-10-01 has 28 commits',()=>({ok:C[ix('2026-10-01')]==28,detail:'got '+C[ix('2026-10-01')]})],\n['rings: 2026-10-19 has 67, the maximum',()=>({ok:C[ix('2026-10-19')]==67&&bi==ix('2026-10-19'),detail:'got '+C[ix('2026-10-19')]+', busiest index '+bi})],\n['rings: first day 2026-09-05',()=>({ok:Y.first=='2026-09-05'&&C[0]>0,detail:'first '+Y.first+', commits '+C[0]})],\n['rings: backend born 2026-09-09',()=>({ok:String(fb||'').slice(0,10)=='2026-09-09',detail:'born '+fb})],\n['rings: eight rings, busiest in week 7',()=>({ok:R.length==8&&bw==6&&Math.abs(t0+st*bi-tb)<1e-6,detail:'rings '+R.length+', busy ring '+(bw+1)})]].forEach(a=>F.test(...a))})();\n",
