      "outputType": "text",
      "output": "(() => {\n  const F = window.F, S = F.SHEET, L = S.look, C = L.camera, D = L.days, R = Math.PI / 180;\n  const t1 = D.t0 + D.step * (D.count - 1);\n  const dist = T => F.clamp(C.distanceFactor * L.worldRadius * Math.sqrt(F.ease.inOut(F.remap(T, D.t0, t1, 0, 1))), C.distanceMin, C.distanceMax);\n  F.cam = T => {\n    const d = dist(T), a = C.azimuth0 + C.azimuthRate * T, e = C.elevationDeg * R, h = d * Math.cos(e);\n    return { position: [h * Math.sin(a), d * Math.sin(e), h * Math.cos(a)], target: [0, 0, 0], fov: C.fov };\n  };\n  for (const s of S.shots.filter(s => s.module === 'camera')) {\n    let r;\n    F.scene(s.id, {\n      start: s.start, end: s.end,\n      setup(root) { r = new F.THREE.Object3D(); r.name = 'camera-rig'; root.add(r); },\n      update(T) { const c = F.cam(T); r.position.set(...c.position); r.lookAt(...c.target); }\n    });\n  }\n  F.test('camera: orbit and pull back', () => {\n    const b = [], d = T => Math.hypot(...F.cam(T).position);\n    let p = d(0);\n    for (let i = 0; i < F.LENGTH * F.FPS; i++) {\n      const T = i / F.FPS, c = F.cam(T), q = d(T);\n      if (![...c.position, ...c.target, c.fov].every(Number.isFinite)) { b.push('NaN at ' + T); break; }\n      if (q + 1e-9 < p) { b.push('zooms in at ' + T.toFixed(3)); break; }\n      p = q;\n    }\n    const d0 = d(0), dE = d(t1), dZ = d(F.LENGTH - 1 / F.FPS);\n    if (Math.abs(d0 - C.distanceMin) > 0.01) b.push('start ' + d0.toFixed(2));\n    if (Math.abs(dE - C.distanceMax) > 0.01 || Math.abs(dZ - dE) > 0.01) b.push('end ' + dE.toFixed(2));\n    return { ok: !b.length, detail: b.length ? b.join('; ') : 'distance ' + d0.toFixed(1) + ' -> ' + dE.toFixed(1) + ', fov ' + C.fov };\n  });\n})();\n",
